// client/src/api/auth.js

import axios from "axios";

const BASE_URL = "http://localhost:8000/api";

// User registration
export const registerUser = (data) =>
  axios.post(`${BASE_URL}/user/register`, data);

// User login
export const loginUser = (data) =>
  axios.post(`${BASE_URL}/user/login`, data);

// Authority login (assuming authority login is at /auth/login)
export const loginAuthority = (data) =>
  axios.post(`${BASE_URL}/auth/login`, data);

// Get user profile (JWT required)
export const getUserProfile = (token) =>
  axios.get(`${BASE_URL}/user/user-profile`, {
    headers: { Authorization: `Bearer ${token}` }
  });

// Change password (JWT required)
export const changePassword = (data, token) =>
  axios.post(`${BASE_URL}/user/change-password`, data, {
    headers: { Authorization: `Bearer ${token}` }
  });
